/* Generated by consolidate-runtime.yml. Exact source order; no logic rewrite. */

/* ===== hotfix-v139.js ===== */
/* GRID SHIFT v1.3.9 — BOMBS clarity pass
   Keep the interesting risk/reward from v1.3.8, remove the hard-to-read parts:
   - Defuse a bomb by clearing a row/column that contains it.
   - A defused bomb clears exactly its visible 3x3 frame; bombs inside that frame chain.
   - Fuse reaching 0 is GAME OVER again. No rubble, no hidden secondary rule.
   - Bomb messages are visual and short; long transient sentences are removed.
*/
(function(){
  'use strict';

  const BOMB_ENGINE_VERSION=139;
  const previousTickBombs=tickBombs;
  const previousRenderBoard=renderBoard;
  const previousRenderModeStat=renderModeStat;
  const previousLoadSlot=loadSlot;
  const previousNewRun=newRun;
  const previousAnnounce=announce;
  const previousModeDemoHTML=modeDemoHTML;

  function inBoard(x,y){return x>=0&&y>=0&&x<state.size&&y<state.size;}

  function removeLegacyRubble(){
    if(state?.mode!=='BOMBS')return;
    if(Array.isArray(state.bombRubble)){
      for(const r of state.bombRubble){
        if(!Number.isInteger(r?.x)||!Number.isInteger(r?.y)||!inBoard(r.x,r.y))continue;
        if(Number(state.board[r.y][r.x])===7)state.board[r.y][r.x]=0;
      }
    }
    state.bombRubble=[];
    state.bombEngineVersion=BOMB_ENGINE_VERSION;
  }

  /* One rule for failure: if the visible number reaches zero, the run ends. */
  tickBombs=function(){
    if(state?.mode!=='BOMBS')return previousTickBombs();
    if(!Array.isArray(state.bombs)||!state.bombs.length)return;
    for(const b of state.bombs)b.t--;
    const doomed=state.bombs.find(b=>b.t<=0);
    if(doomed){
      triggerBombGameOver(doomed);
      return;
    }
    const min=Math.min(...state.bombs.map(b=>b.t));
    if(min<=2)beep('danger');
  };

  function shortChainBadge(count){
    if(!boardEl||count<2)return;
    const e=document.createElement('b');
    e.className='bomb-chain-badge-v139';
    e.textContent=`×${count}`;
    boardEl.appendChild(e);
    setTimeout(()=>e.remove(),700);
  }

  /* v1.3.8 translated BOMB CLEARED into a long sentence. Keep only an optional
     x2/x3 badge: the blast itself explains the rest. */
  announce=function(text,strong=false){
    if(state?.mode==='BOMBS'&&typeof text==='string'&&text.startsWith('BOMB CLEARED')){
      const b=state.bombLastBlast;
      state.bombLastBlast=null;
      if(b?.count>1)shortChainBadge(b.count);
      return;
    }
    if(state?.mode==='BOMBS'&&typeof text==='string'&&(text.includes('UNCONTROLLED')||text.includes('RUBBLE')||text.includes('CHAIN FAILURE')))return;
    return previousAnnounce(text,strong);
  };

  function addBlastFrame(b){
    const minX=Math.max(0,b.x-1),maxX=Math.min(state.size-1,b.x+1);
    const minY=Math.max(0,b.y-1),maxY=Math.min(state.size-1,b.y+1);
    const a=cellEls[minY]?.[minX],z=cellEls[maxY]?.[maxX];
    if(!a||!z)return;
    const f=document.createElement('i');
    f.className='bomb-zone-frame-v139'+(b.t<=2?' hot':'');
    f.style.left=`${a.offsetLeft-1}px`;
    f.style.top=`${a.offsetTop-1}px`;
    f.style.width=`${z.offsetLeft+z.offsetWidth-a.offsetLeft+2}px`;
    f.style.height=`${z.offsetTop+z.offsetHeight-a.offsetTop+2}px`;
    boardEl.appendChild(f);
  }

  renderBoard=function(){
    const out=previousRenderBoard();
    if(state?.mode!=='BOMBS')return out;

    /* Remove v1.3.8's cell-by-cell haze and mystery symbols. One clean frame now
       means one thing: this is exactly what a successful bomb blast will clear. */
    for(const row of cellEls||[])for(const c of row||[]){
      if(!c)continue;
      c.classList.remove('bomb-zone-v138','bomb-zone-hot-v138','bomb-chainable-v138','rubble-v138');
    }
    boardEl.querySelectorAll('.bomb-zone-frame-v139').forEach(e=>e.remove());
    for(const b of state.bombs||[])addBlastFrame(b);
    return out;
  };

  renderModeStat=function(){
    previousRenderModeStat();
    if(state?.mode!=='BOMBS')return;
    const min=state.bombs?.length?Math.min(...state.bombs.map(b=>b.t)):null;
    modeStatEl.textContent=min===null?'●':`●  ${min}`;
    modeStatEl.classList.toggle('urgent',min!==null&&min<=2);
    modeStatEl.classList.add('visible');
  };

  loadSlot=async function(mode,size){
    await previousLoadSlot(mode,size);
    if(state?.mode==='BOMBS'){
      removeLegacyRubble();
      /* Old v1.3.8 saves can contain a zero/invalid fuse from the recoverable-blast
         experiment. Clamp only live bombs, then use the new simple rule from here. */
      if(Array.isArray(state.bombs))for(const b of state.bombs)b.t=Math.max(1,Math.min(5,Number(b.t)||5));
      renderAll();scheduleSave(true);
    }
  };

  newRun=function(keepBest=true){
    const out=previousNewRun(keepBest);
    if(state?.mode==='BOMBS'){
      state.bombEngineVersion=BOMB_ENGINE_VERSION;
      state.bombRubble=[];
      state.bombLastBlast=null;
      renderAll();scheduleSave(true);
    }
    return out;
  };

  /* Selector animation: line touches bomb -> the framed 3x3 area flashes.
     No explanatory sentence is required. */
  modeDemoHTML=function(id){
    if(id!=='BOMBS')return previousModeDemoHTML(id);
    let cells='';
    for(let x=0;x<5;x++)cells+=miniCell(x,2,'md-blue bomb-demo-line-v139');
    return `<div class="mode-demo demo-bombs demo-bombs-v139"><div class="mini-board">${cells}<i class="bomb-demo-zone-v139"></i><b class="bomb-demo-core-v139">3</b></div></div>`;
  };

  queueMicrotask(()=>{
    try{
      buildMenu();renderMenu();
      if(state?.mode==='BOMBS'){
        removeLegacyRubble();renderAll();scheduleSave(true);
      }
    }catch(_){ }
  });
})();


/* ===== hotfix-v140.js ===== */
/* GRID SHIFT v1.4.0 — BOMBS: the player places the bomb
   One of the three tray pieces carries a visible ●4 on one of its cells.
   Where that piece is placed becomes the bomb position. Existing bombs count down
   on later moves; the newly planted bomb does not lose a turn immediately.
   Clearing a row/column through a bomb still triggers the visible 3x3 controlled
   blast from v1.3.8/1.3.9, including adjacent-bomb chain reactions.
*/
(function(){
  'use strict';

  const BOMB_ENGINE_VERSION=140;
  const CARGO_FUSE=4;

  const baseTryPlace=tryPlace;
  const baseTickBombs=tickBombs;
  const baseSpawnBomb=spawnBomb;
  const baseCompleteTray=completeTray;
  const baseRenderTray=renderTray;
  const baseMakePiece=makePiece;
  const baseRotateTrayPiece=rotateTrayPiece;
  const baseRenderModeStat=renderModeStat;
  const baseLoadSlot=loadSlot;
  const baseNewRun=newRun;
  const baseModeDemoHTML=modeDemoHTML;

  function k(x,y){return `${x},${y}`;}

  function validCargo(){
    const c=state?.bombCargo;
    if(state?.mode!=='BOMBS'||!c||!Number.isInteger(c.idx))return false;
    const shape=state.tray?.[c.idx];
    if(!shape||!Array.isArray(shape.cells))return false;
    return shape.cells.some(([x,y])=>x===c.x&&y===c.y);
  }

  function clearCargoDecoration(){
    for(const p of state?.tray||[]){
      if(!p)continue;
      delete p.bombCell;delete p.bombFuse;
    }
  }

  function decorateCargo(){
    if(state?.mode!=='BOMBS')return;
    clearCargoDecoration();
    if(!validCargo())return;
    const c=state.bombCargo,p=state.tray[c.idx];
    p.bombCell=[c.x,c.y];p.bombFuse=c.fuse||CARGO_FUSE;
  }

  function chooseCargoIndex(){
    const ids=(state.tray||[]).map((p,i)=>p?i:-1).filter(i=>i>=0);
    if(!ids.length)return -1;
    /* A bomb on a medium/large piece creates a real placement choice. Avoid dots
       and dominoes when a more interesting carrier is available. */
    const interesting=ids.filter(i=>state.tray[i].cells.length>=3);
    const pool=interesting.length?interesting:ids;
    return pool[Math.floor(Math.random()*pool.length)];
  }

  function chooseCargoCell(shape){
    if(!shape?.cells?.length)return [0,0];
    /* Keep variety, but mildly prefer cells away from the exact centroid so rotation
       can change the bomb's landing position in a visible, strategic way. */
    const cx=shape.cells.reduce((s,c)=>s+c[0],0)/shape.cells.length;
    const cy=shape.cells.reduce((s,c)=>s+c[1],0)/shape.cells.length;
    const ranked=shape.cells.map(([x,y])=>({x,y,d:Math.abs(x-cx)+Math.abs(y-cy)})).sort((a,b)=>b.d-a.d);
    const pool=ranked.slice(0,Math.max(1,Math.ceil(ranked.length*.65)));
    const p=pool[Math.floor(Math.random()*pool.length)];
    return [p.x,p.y];
  }

  function armCargo(force=false){
    if(state?.mode!=='BOMBS'||state.gameOver)return;
    if(validCargo()){decorateCargo();return;}
    if(!force&&state.bombCargoDone)return;
    const idx=chooseCargoIndex();if(idx<0)return;
    const [x,y]=chooseCargoCell(state.tray[idx]);
    state.bombCargo={idx,x,y,fuse:CARGO_FUSE};
    state.bombCargoDone=false;
    decorateCargo();
  }

  function rotateCoord(shape,coord){
    if(!shape||!coord)return coord;
    const h=Math.max(...shape.cells.map(c=>c[1]))+1;
    const raw=shape.cells.map(([x,y])=>[h-1-y,x]);
    const minX=Math.min(...raw.map(c=>c[0])),minY=Math.min(...raw.map(c=>c[1]));
    return [h-1-coord[1]-minX,coord[0]-minY];
  }

  /* Carry the marker with the physical piece when the player rotates it. */
  rotateTrayPiece=function(idx,wrap=null){
    if(state?.mode!=='BOMBS'||!validCargo()||state.bombCargo.idx!==idx)return baseRotateTrayPiece(idx,wrap);
    const oldShape=state.tray[idx],old=[state.bombCargo.x,state.bombCargo.y];
    const next=rotateCoord(oldShape,old);
    const ok=baseRotateTrayPiece(idx,wrap);
    if(ok){
      state.bombCargo.x=next[0];state.bombCargo.y=next[1];
      decorateCargo();renderTray();scheduleSave();
    }
    return ok;
  };

  /* The same ●4 marker is rendered in the tray and in the lifted drag ghost. */
  makePiece=function(shape,role='tray',unit=null,gap=null){
    const art=baseMakePiece(shape,role,unit,gap);
    if(state?.mode==='BOMBS'&&Array.isArray(shape?.bombCell)){
      const [bx,by]=shape.bombCell;
      const i=shape.cells.findIndex(([x,y])=>x===bx&&y===by);
      const block=art.querySelectorAll('.piece-block')[i];
      if(block){block.classList.add('bomb-cargo-v140');block.dataset.bomb=String(shape.bombFuse||CARGO_FUSE);}
    }
    return art;
  };

  renderTray=function(){
    if(state?.mode==='BOMBS')decorateCargo();
    const out=baseRenderTray();
    if(state?.mode==='BOMBS'&&validCargo()){
      trayEl.querySelector(`.piece-wrap[data-idx="${state.bombCargo.idx}"]`)?.classList.add('bomb-carrier-v140');
    }
    return out;
  };

  /* Random board spawning is retired. Bombs enter play only through the marked
     tray piece, so the player owns the placement decision. */
  spawnBomb=function(avoidCells=[]){
    if(state?.mode==='BOMBS')return false;
    return baseSpawnBomb(avoidCells);
  };

  /* Existing bombs lose one turn after each successful placement. The bomb planted
     by that very placement stays at 4, so the number shown on the tray is truthful. */
  tickBombs=function(){
    if(state?.mode!=='BOMBS')return baseTickBombs();
    if(!Array.isArray(state.bombs)||!state.bombs.length){state.bombFreshKey=null;return;}
    const fresh=state.bombFreshKey||null;
    for(const b of state.bombs){if(k(b.x,b.y)!==fresh)b.t--;}
    state.bombFreshKey=null;
    const doomed=state.bombs.find(b=>b.t<=0);
    if(doomed){triggerBombGameOver(doomed);return;}
    const min=Math.min(...state.bombs.map(b=>b.t));
    if(min<=2)beep('danger');
  };

  /* v1.3.8's controlled-blast engine remains authoritative. We insert the cargo
     bomb into state.bombs before the normal placement path scans line clears; this
     means a bomb can be deliberately planted straight into a completed line and
     detonate immediately. */
  tryPlace=function(idx,x,y){
    if(state?.mode!=='BOMBS')return baseTryPlace(idx,x,y);
    if(state.gameOver||resolving)return false;

    decorateCargo();
    const shape=state.tray[idx];
    if(!shape||!Core.canPlace(state.board,shape,x,y,state.size))return false;

    const carrier=validCargo()&&state.bombCargo.idx===idx;
    let planted=null,oldCargo=null,oldDone=!!state.bombCargoDone;
    if(carrier){
      oldCargo={...state.bombCargo};
      const local=Array.isArray(shape.bombCell)?shape.bombCell:[oldCargo.x,oldCargo.y];
      planted={x:x+local[0],y:y+local[1],t:CARGO_FUSE,source:'player',uid:`p${Date.now()}_${Math.random().toString(36).slice(2,7)}`};
      state.bombs.push(planted);
      state.bombFreshKey=k(planted.x,planted.y);
      state.bombCargo=null;
      state.bombCargoDone=true;
      delete shape.bombCell;delete shape.bombFuse;
    }

    const ok=baseTryPlace(idx,x,y);
    if(!ok&&carrier){
      state.bombs=state.bombs.filter(b=>b.uid!==planted.uid);
      state.bombFreshKey=null;
      state.bombCargo=oldCargo;
      state.bombCargoDone=oldDone;
      decorateCargo();renderAll();
    }
    return ok;
  };

  completeTray=function(){
    if(state?.mode!=='BOMBS')return baseCompleteTray();
    const out=baseCompleteTray();
    if(!state.gameOver){
      state.bombCargo=null;state.bombCargoDone=false;
      armCargo(true);
    }
    return out;
  };

  renderModeStat=function(){
    baseRenderModeStat();
    if(state?.mode!=='BOMBS')return;
    const min=state.bombs?.length?Math.min(...state.bombs.map(b=>b.t)):null;
    const ready=validCargo();
    if(min===null)modeStatEl.textContent=ready?'●4  ON PIECE':'●';
    else modeStatEl.textContent=ready?`● ${min}   +●4`:`● ${min}`;
    modeStatEl.classList.toggle('urgent',min!==null&&min<=2);
    modeStatEl.classList.add('visible');
  };

  function upgradeBombMode(){
    if(state?.mode!=='BOMBS')return;
    if(state.bombEngineVersion!==BOMB_ENGINE_VERSION){
      /* Remove legacy randomly spawned bombs so the new rule starts unambiguously.
         Only old bomb cells are cleared; the rest of the board, score and best stay. */
      for(const b of state.bombs||[]){
        if(Number.isInteger(b?.x)&&Number.isInteger(b?.y)&&state.board?.[b.y]?.[b.x]===6)state.board[b.y][b.x]=0;
      }
      state.bombs=[];state.bombRubble=[];state.bombLastBlast=null;state.bombFreshKey=null;
      state.bombCargo=null;state.bombCargoDone=false;state.bombEngineVersion=BOMB_ENGINE_VERSION;
      armCargo(true);
    }else{
      state.bombRubble=[];state.bombFreshKey=null;
      if(validCargo())decorateCargo();
      else if(!state.bombCargoDone)armCargo(true);
    }
  }

  loadSlot=async function(mode,size){
    await baseLoadSlot(mode,size);
    if(state?.mode==='BOMBS'){
      upgradeBombMode();renderAll();scheduleSave(true);
    }
  };

  newRun=function(keepBest=true){
    const out=baseNewRun(keepBest);
    if(state?.mode==='BOMBS'){
      state.bombs=[];state.bombRubble=[];state.bombLastBlast=null;state.bombFreshKey=null;
      state.bombCargo=null;state.bombCargoDone=false;state.bombEngineVersion=BOMB_ENGINE_VERSION;
      armCargo(true);renderAll();scheduleSave(true);
    }
    return out;
  };

  /* Menu demo now teaches the defining rule: the bomb arrives ON a piece. */
  modeDemoHTML=function(id){
    if(id!=='BOMBS')return baseModeDemoHTML(id);
    const cells=miniCell(1,0,'md-blue bomb-piece-cell-v140')+miniCell(1,1,'md-blue bomb-piece-cell-v140')+miniCell(2,1,'md-blue bomb-piece-cell-v140');
    return `<div class="mode-demo demo-bombs demo-bombs-v140"><div class="mini-board">${cells}<b class="bomb-piece-core-v140">4</b><em class="bomb-piece-arrow-v140">↓</em><i class="bomb-demo-zone-v140"></i></div></div>`;
  };

  queueMicrotask(()=>{
    try{
      buildMenu();renderMenu();
      if(state?.mode==='BOMBS'){upgradeBombMode();renderAll();scheduleSave(true);}
    }catch(_){ }
  });
})();


/* ===== hotfix-v141.js ===== */
/* GRID SHIFT v1.4.1 — BOMBS: mandatory bomb-first round
   Each 3-piece tray begins with exactly one armed carrier. The other two pieces are
   locked until the carrier is placed. The carrier is chosen only from pieces that
   can be placed FIRST while still leaving a route to place both remaining pieces.
   This removes the dominant "save the bomb for last" strategy without creating an
   unfair tray that needed a different piece first. */
(function(){
  'use strict';

  const FORCE_VERSION=141;
  const FUSE=4;

  const baseRenderTray=renderTray;
  const baseRotateTrayPiece=rotateTrayPiece;
  const baseStartDrag=startDrag;
  const baseCompleteTray=completeTray;
  const baseRenderModeStat=renderModeStat;
  const baseLoadSlot=loadSlot;
  const baseNewRun=newRun;

  function liveIds(tray){
    return (tray||[]).map((p,i)=>p?i:-1).filter(i=>i>=0);
  }

  function carrierIndex(){
    if(state?.mode!=='BOMBS')return -1;
    const c=state.bombCargo;
    if(!c||!Number.isInteger(c.idx)||!state.tray?.[c.idx])return -1;
    return c.idx;
  }

  function clearBombMarks(){
    for(const p of state?.tray||[]){
      if(!p)continue;
      delete p.bombCell;
      delete p.bombFuse;
    }
  }

  function chooseBombCell(shape){
    if(!shape?.cells?.length)return [0,0];
    const cx=shape.cells.reduce((s,c)=>s+c[0],0)/shape.cells.length;
    const cy=shape.cells.reduce((s,c)=>s+c[1],0)/shape.cells.length;
    const ranked=shape.cells
      .map(([x,y])=>({x,y,d:Math.abs(x-cx)+Math.abs(y-cy)}))
      .sort((a,b)=>b.d-a.d);
    const pool=ranked.slice(0,Math.max(1,Math.ceil(ranked.length*.65)));
    const p=pool[Math.floor(Math.random()*pool.length)];
    return [p.x,p.y];
  }

  function hasPlacementAfter(board,piece,size){
    if(!piece)return false;
    for(const shape of Core.modeRotations(piece,'BOMBS')){
      if(Core.placements(board,shape,size).length)return true;
    }
    return false;
  }

  /* With only two pieces remaining, do an exact two-step check. We intentionally
     ignore the bomb's extra 3x3 reward while planning: a real blast only removes
     more cells, so a route proven here remains safe in actual play. */
  function remainingTwoFit(board,tray,a,b,size){
    for(const secondIdx of [a,b]){
      const thirdIdx=secondIdx===a?b:a;
      const piece=tray[secondIdx];
      if(!piece)continue;
      for(const shape of Core.modeRotations(piece,'BOMBS')){
        for(const [x,y] of Core.placements(board,shape,size)){
          const sim=Core.simulatePlace(board,shape,x,y,'BOMBS',size);
          if(sim&&hasPlacementAfter(sim.board,tray[thirdIdx],size))return true;
        }
      }
    }
    return false;
  }

  function carrierCanLead(board,tray,idx,size){
    const rest=liveIds(tray).filter(i=>i!==idx);
    if(rest.length!==2)return false;
    const piece=tray[idx];
    if(!piece)return false;
    for(const shape of Core.modeRotations(piece,'BOMBS')){
      for(const [x,y] of Core.placements(board,shape,size)){
        const sim=Core.simulatePlace(board,shape,x,y,'BOMBS',size);
        if(sim&&remainingTwoFit(sim.board,tray,rest[0],rest[1],size))return true;
      }
    }
    return false;
  }

  function chooseSafeCarrier(){
    const ids=liveIds(state.tray);
    if(ids.length!==3)return -1;
    /* Prefer a real polyomino so the forced decision is spatially interesting, but
       fairness wins: if only a small piece can safely lead, use it. */
    const preferred=ids.filter(i=>state.tray[i].cells.length>=3);
    const order=[...preferred.sort(()=>Math.random()-.5),...ids.filter(i=>!preferred.includes(i)).sort(()=>Math.random()-.5)];
    for(const idx of order){
      if(carrierCanLead(state.board,state.tray,idx,state.size))return idx;
    }
    return -1;
  }

  function installSafeCarrier({freshTray=false}={}){
    if(state?.mode!=='BOMBS'||state.gameOver)return;
    if(freshTray||liveIds(state.tray).length!==3){
      state.tray=Core.generateFairTray(state.board,'BOMBS',state.size,Math.random,state.moves);
    }
    clearBombMarks();
    let idx=chooseSafeCarrier();
    /* generateFairTray already guarantees a complete route in some order. This is
       an emergency guard only; a second fair tray should make a fixed-first route
       discoverable even if a malformed legacy tray slipped through. */
    if(idx<0){
      state.tray=Core.generateFairTray(state.board,'BOMBS',state.size,Math.random,state.moves);
      idx=chooseSafeCarrier();
    }
    if(idx<0)idx=liveIds(state.tray)[0]??-1;
    if(idx<0)return;
    const [x,y]=chooseBombCell(state.tray[idx]);
    state.bombCargo={idx,x,y,fuse:FUSE};
    state.bombCargoDone=false;
    state.bombFirstVersion=FORCE_VERSION;
  }

  /* Lock the two support pieces. Disabled is deliberate: they cannot be dragged,
     tapped to rotate, or accidentally selected until the bomb has been planted. */
  renderTray=function(){
    const out=baseRenderTray();
    if(state?.mode!=='BOMBS')return out;
    const forced=carrierIndex();
    if(forced<0)return out;
    trayEl.querySelectorAll('.piece-wrap').forEach((wrap,i)=>{
      const piece=state.tray?.[i];
      if(!piece)return;
      if(i===forced){
        wrap.classList.add('bomb-first-v141');
        wrap.setAttribute('aria-label','Bomb piece — place this first');
      }else{
        wrap.classList.add('bomb-locked-v141');
        wrap.disabled=true;
        wrap.setAttribute('aria-disabled','true');
      }
    });
    return out;
  };

  rotateTrayPiece=function(idx,wrap=null){
    if(state?.mode==='BOMBS'){
      const forced=carrierIndex();
      if(forced>=0&&idx!==forced)return false;
    }
    return baseRotateTrayPiece(idx,wrap);
  };

  startDrag=function(e,idx,wrap){
    if(state?.mode==='BOMBS'){
      const forced=carrierIndex();
      if(forced>=0&&idx!==forced){e?.preventDefault?.();return;}
    }
    return baseStartDrag(e,idx,wrap);
  };

  completeTray=function(){
    if(state?.mode!=='BOMBS')return baseCompleteTray();
    const out=baseCompleteTray();
    if(!state.gameOver)installSafeCarrier();
    return out;
  };

  /* The bomb drawn on the carrier is the instruction. Keep the top status devoted
     only to bombs that are already ticking on the board. */
  renderModeStat=function(){
    baseRenderModeStat();
    if(state?.mode!=='BOMBS')return;
    const min=state.bombs?.length?Math.min(...state.bombs.map(b=>b.t)):null;
    modeStatEl.textContent=min===null?'●':`●  ${min}`;
    modeStatEl.classList.toggle('urgent',min!==null&&min<=2);
    modeStatEl.classList.add('visible');
  };

  function upgradeRound(){
    if(state?.mode!=='BOMBS'||state.gameOver)return;
    if(state.bombFirstVersion!==FORCE_VERSION){
      /* Preserve board, score, best and any live bombs. Only replace the current
         three-piece tray once so the new mandatory-first rule begins fairly. */
      installSafeCarrier({freshTray:true});
    }else if(carrierIndex()<0&&liveIds(state.tray).length===3&&!state.bombCargoDone){
      installSafeCarrier();
    }
  }

  loadSlot=async function(mode,size){
    await baseLoadSlot(mode,size);
    if(state?.mode==='BOMBS'){
      upgradeRound();renderAll();scheduleSave(true);
    }
  };

  newRun=function(keepBest=true){
    const out=baseNewRun(keepBest);
    if(state?.mode==='BOMBS'){
      state.bombFirstVersion=FORCE_VERSION;
      installSafeCarrier();renderAll();scheduleSave(true);
    }
    return out;
  };

  queueMicrotask(()=>{
    try{
      if(state?.mode==='BOMBS'){upgradeRound();renderAll();scheduleSave(true);}
    }catch(_){ }
  });
})();


/* ===== hotfix-v142.js ===== */
/* GRID SHIFT v1.4.2 — BOMBS dedicated diverse tray ecology
   Goal: keep v1.4.1's mandatory bomb-first fairness, but stop the repeated
   medium-piece feel. Every successful BOMBS tray is drawn from three different
   shape families, including rarer pentominoes, while still proving that the bomb
   carrier can be placed first and the other two pieces can subsequently be placed.
   If the diversity search cannot prove a safe route quickly, the known-safe v1.4.1
   tray is left untouched rather than risking an unfair round. */
(function(){
  'use strict';

  const VERSION=142;
  const FUSE=4;
  const previousCompleteTray=completeTray;
  const previousNewRun=newRun;
  const previousLoadSlot=loadSlot;

  const FAMILY_POOLS={
    BAR:['i3h','i3h','i4h','i4h','i5h'],
    CORNER:['l3a','l3a','l4a','l4a'],
    BLOCK:['sq2','sq2','sq2','sq3'],
    TEE:['t4u','t4u','t4u','plus5'],
    ZIG:['z4h','z4h','s4h','w5'],
    POCKET:['p5','p5','u5','u5']
  };
  const FAMILIES=Object.keys(FAMILY_POOLS);

  function clone(id){
    const s=Core.SHAPE_BY_ID[id];
    return s?Core.deepClone(s):null;
  }

  function shuffle(a){
    const out=a.slice();
    for(let i=out.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[out[i],out[j]]=[out[j],out[i]];}
    return out;
  }

  function rotateRandom(shape){
    if(!shape)return null;
    let s=shape;
    const turns=Math.floor(Math.random()*4);
    for(let i=0;i<turns;i++)s=Core.rotateShape(s);
    return s;
  }

  function familyOf(shape){
    if(!shape)return '';
    const id=String(shape.id||'');
    if(/^i[23456]/.test(id))return 'BAR';
    if(/^l[346]/.test(id))return 'CORNER';
    if(/^sq|^rect/.test(id))return 'BLOCK';
    if(/^t4|^plus/.test(id))return 'TEE';
    if(/^z4|^s4|^w5|^stair/.test(id))return 'ZIG';
    if(/^p5|^u5/.test(id))return 'POCKET';
    if(id==='dot')return 'TINY';
    return 'OTHER';
  }

  function recentHistory(){
    return Array.isArray(state?.bombTrayHistory)?state.bombTrayHistory.slice(-5):[];
  }

  function familyCombos(){
    const hist=recentHistory();
    const counts=Object.fromEntries(FAMILIES.map(f=>[f,0]));
    for(const h of hist){
      for(const f of Array.isArray(h?.families)?h.families:[])if(f in counts)counts[f]++;
    }
    const lastSig=hist.length?hist[hist.length-1].signature:'';
    const combos=[];
    for(let a=0;a<FAMILIES.length;a++)for(let b=a+1;b<FAMILIES.length;b++)for(let c=b+1;c<FAMILIES.length;c++){
      const fam=[FAMILIES[a],FAMILIES[b],FAMILIES[c]];
      const signature=fam.slice().sort().join('+');
      let score=120-(counts[fam[0]]+counts[fam[1]]+counts[fam[2]])*13;
      if(signature===lastSig)score-=100;
      else if(hist.some(h=>h?.signature===signature))score-=28;
      score+=Math.random()*18;
      combos.push({fam,score,signature});
    }
    combos.sort((x,y)=>y.score-x.score);
    return combos;
  }

  function pickShape(family,fill){
    let pool=(FAMILY_POOLS[family]||[]).slice();
    /* On a crowded board keep the rare big shapes alive, but reduce their frequency
       instead of removing them. Variety should survive late-game without becoming
       a stream of impossible 3x3/5-cell pieces. */
    if(fill>=58){
      const lighter=pool.filter(id=>!['sq3','plus5','w5','u5'].includes(id));
      if(lighter.length&&Math.random()<.68)pool=lighter;
    }
    const id=pool[Math.floor(Math.random()*pool.length)];
    return rotateRandom(clone(id));
  }

  function makeTray(families){
    const fill=Core.boardFill(state.board);
    const tray=families.map(f=>pickShape(f,fill));
    return tray.every(Boolean)?tray:null;
  }

  function placementRecords(board,piece,size,limit=9999){
    const out=[];
    for(const shape of Core.modeRotations(piece,'BOMBS')){
      for(const [x,y] of Core.placements(board,shape,size))out.push({shape,x,y});
    }
    const mixed=shuffle(out);
    return mixed.length>limit?mixed.slice(0,limit):mixed;
  }

  function thirdHasMove(board,piece,size){
    return !!piece&&Core.hasModePlacement(board,piece,size,'BOMBS');
  }

  function remainingTwoFit(board,tray,a,b,size,budget){
    for(const secondIdx of shuffle([a,b])){
      const thirdIdx=secondIdx===a?b:a;
      for(const m of placementRecords(board,tray[secondIdx],size,56)){
        if(++budget.nodes>budget.max)return false;
        const sim=Core.simulatePlace(board,m.shape,m.x,m.y,'BOMBS',size);
        if(sim&&thirdHasMove(sim.board,tray[thirdIdx],size))return true;
      }
    }
    return false;
  }

  function carrierCanLead(board,tray,idx,size,budget){
    const rest=[0,1,2].filter(i=>i!==idx);
    for(const m of placementRecords(board,tray[idx],size,72)){
      if(++budget.nodes>budget.max)return false;
      const sim=Core.simulatePlace(board,m.shape,m.x,m.y,'BOMBS',size);
      if(sim&&remainingTwoFit(sim.board,tray,rest[0],rest[1],size,budget))return true;
    }
    return false;
  }

  function safeCarriers(tray){
    const out=[];
    const lastFamily=state?.bombLastCarrierFamily||'';
    for(const idx of shuffle([0,1,2])){
      const budget={nodes:0,max:6200};
      if(carrierCanLead(state.board,tray,idx,state.size,budget)){
        const fam=familyOf(tray[idx]);
        const n=tray[idx].cells.length;
        let score=0;
        if(fam!==lastFamily)score+=24;
        if(n>=3&&n<=5)score+=12;
        if(['POCKET','ZIG','TEE'].includes(fam))score+=8;
        score+=Math.random()*12;
        out.push({idx,fam,score});
      }
    }
    out.sort((a,b)=>b.score-a.score);
    return out;
  }

  function chooseBombCell(shape){
    const cx=shape.cells.reduce((s,c)=>s+c[0],0)/shape.cells.length;
    const cy=shape.cells.reduce((s,c)=>s+c[1],0)/shape.cells.length;
    const ranked=shape.cells.map(([x,y])=>({x,y,d:Math.abs(x-cx)+Math.abs(y-cy)})).sort((a,b)=>b.d-a.d);
    const pool=ranked.slice(0,Math.max(1,Math.ceil(ranked.length*.7)));
    const p=pool[Math.floor(Math.random()*pool.length)];
    return [p.x,p.y];
  }

  function clearBombMarks(){
    for(const p of state?.tray||[]){if(p){delete p.bombCell;delete p.bombFuse;}}
  }

  function installTray(tray,carrier,combo){
    clearBombMarks();
    state.tray=tray;
    const shape=state.tray[carrier.idx];
    const [x,y]=chooseBombCell(shape);
    state.bombCargo={idx:carrier.idx,x,y,fuse:FUSE};
    state.bombCargoDone=false;
    state.bombFirstVersion=141;
    state.bombDiversityVersion=VERSION;
    state.bombLastCarrierFamily=carrier.fam;
    shape.bombCell=[x,y];shape.bombFuse=FUSE;

    const history=recentHistory();
    history.push({
      signature:combo.signature,
      families:combo.fam.slice(),
      ids:tray.map(p=>String(p.id||'')),
      carrier:carrier.fam
    });
    state.bombTrayHistory=history.slice(-5);
  }

  function tryInstallDiverseTray(){
    if(state?.mode!=='BOMBS'||state.gameOver)return false;
    const start=performance.now();
    const combos=familyCombos();

    /* Two shape rolls per family-combination gives rare pieces a real chance while
       keeping tray generation comfortably bounded on iPhone. */
    for(const combo of combos.slice(0,14)){
      for(let variant=0;variant<2;variant++){
        if(performance.now()-start>38)return false;
        const tray=makeTray(combo.fam);
        if(!tray)continue;
        const carriers=safeCarriers(tray);
        if(carriers.length){installTray(tray,carriers[0],combo);return true;}
      }
    }
    return false;
  }

  function fullTray(){return Array.isArray(state?.tray)&&state.tray.filter(Boolean).length===3;}

  completeTray=function(){
    if(state?.mode!=='BOMBS')return previousCompleteTray();
    const out=previousCompleteTray();
    if(!state.gameOver)tryInstallDiverseTray();
    return out;
  };

  newRun=function(keepBest=true){
    const out=previousNewRun(keepBest);
    if(state?.mode==='BOMBS'&&!state.gameOver){
      tryInstallDiverseTray();renderAll();scheduleSave(true);
    }
    return out;
  };

  loadSlot=async function(mode,size){
    await previousLoadSlot(mode,size);
    if(state?.mode==='BOMBS'&&!state.gameOver){
      if(state.bombDiversityVersion!==VERSION&&fullTray()){
        tryInstallDiverseTray();renderAll();scheduleSave(true);
      }else{
        state.bombDiversityVersion=VERSION;scheduleSave(true);
      }
    }
  };

  queueMicrotask(()=>{
    try{
      if(state?.mode==='BOMBS'&&!state.gameOver&&state.bombDiversityVersion!==VERSION&&fullTray()){
        tryInstallDiverseTray();renderAll();scheduleSave(true);
      }
    }catch(_){ }
  });
})();


/* ===== hotfix-v143.js ===== */
/* GRID SHIFT v1.4.3 — readability pass
   1) Bomb fuse badges never sit across the carrier's silhouette. The fuse number is
      moved to an exterior edge of the marked cell so the underlying polyomino stays
      readable at a glance, both in the tray and while dragging.
   2) The active mode is always shown above the board. Context stats remain separate.
*/
(function(){
  'use strict';

  const previousMakePiece=makePiece;
  const previousRenderAll=renderAll;

  function bombBadgeDirection(shape){
    if(!shape||!Array.isArray(shape.cells)||!Array.isArray(shape.bombCell))return 'n';
    const [bx,by]=shape.bombCell;
    const occupied=new Set(shape.cells.map(([x,y])=>`${x},${y}`));
    const xs=shape.cells.map(c=>c[0]),ys=shape.cells.map(c=>c[1]);
    const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
    const free={
      n:!occupied.has(`${bx},${by-1}`),
      e:!occupied.has(`${bx+1},${by}`),
      s:!occupied.has(`${bx},${by+1}`),
      w:!occupied.has(`${bx-1},${by}`)
    };

    /* Prefer the true outside edge of the whole silhouette. This matters especially
       on L/T/U pieces where a centered fuse disk can make the shape look like a
       different piece. */
    if(by===minY&&free.n)return 'n';
    if(bx===maxX&&free.e)return 'e';
    if(bx===minX&&free.w)return 'w';
    if(by===maxY&&free.s)return 's';
    for(const d of ['n','e','w','s'])if(free[d])return d;
    return 'n';
  }

  makePiece=function(shape,role='tray',unit=null,gap=null){
    const art=previousMakePiece(shape,role,unit,gap);
    if(state?.mode==='BOMBS'&&Array.isArray(shape?.bombCell)){
      const [bx,by]=shape.bombCell;
      const idx=shape.cells.findIndex(([x,y])=>x===bx&&y===by);
      const block=art.querySelectorAll('.piece-block')[idx];
      if(block){
        block.classList.remove('bomb-badge-n-v143','bomb-badge-e-v143','bomb-badge-s-v143','bomb-badge-w-v143');
        block.classList.add(`bomb-badge-${bombBadgeDirection(shape)}-v143`);
      }
    }
    return art;
  };

  function ensureModeBadge(){
    let badge=document.getElementById('modeBadgeV143');
    if(badge)return badge;
    const shell=document.querySelector('.game-shell');
    const boardWrap=document.querySelector('.board-wrap');
    if(!shell||!boardWrap)return null;
    badge=document.createElement('div');
    badge.id='modeBadgeV143';
    badge.className='mode-badge-v143';
    badge.setAttribute('aria-live','polite');
    shell.insertBefore(badge,boardWrap);
    return badge;
  }

  function syncModeBadge(){
    const badge=ensureModeBadge();
    if(!badge||!state)return;
    const title=MODES[state.mode]?.title||state.mode||'';
    badge.textContent=`MODE  •  ${title}`;
    badge.dataset.mode=String(state.mode||'').toLowerCase();
  }

  renderAll=function(){
    const out=previousRenderAll();
    syncModeBadge();
    return out;
  };

  queueMicrotask(()=>{
    try{syncModeBadge();if(state)renderTray();}catch(_){ }
  });
})();


/* ===== hotfix-v145.js ===== */
/* GRID SHIFT v1.4.5 — robust fuse badge renderer
   Safari can clip pseudo-elements that are pushed outside a transformed block.
   Render the fuse as a sibling of the piece blocks instead, positioned relative
   to the whole piece-art. This keeps the carrier silhouette unobscured and makes
   the badge immune to the transformed block's paint box. */
(function(){
  'use strict';

  const previousMakePiece=makePiece;

  function badgeDirection(shape){
    if(!shape||!Array.isArray(shape.cells)||!Array.isArray(shape.bombCell))return 'n';
    const [bx,by]=shape.bombCell;
    const occupied=new Set(shape.cells.map(([x,y])=>`${x},${y}`));
    const xs=shape.cells.map(c=>c[0]),ys=shape.cells.map(c=>c[1]);
    const minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
    const free={
      n:!occupied.has(`${bx},${by-1}`),
      e:!occupied.has(`${bx+1},${by}`),
      s:!occupied.has(`${bx},${by+1}`),
      w:!occupied.has(`${bx-1},${by}`)
    };
    if(by===minY&&free.n)return 'n';
    if(bx===maxX&&free.e)return 'e';
    if(by===maxY&&free.s)return 's';
    if(bx===minX&&free.w)return 'w';
    for(const d of ['n','e','s','w'])if(free[d])return d;
    return 'n';
  }

  makePiece=function(shape,role='tray',unit=null,gap=null){
    const art=previousMakePiece(shape,role,unit,gap);
    if(state?.mode!=='BOMBS'||!Array.isArray(shape?.bombCell))return art;

    const u=unit||trayUnit(shape),g=gap??4;
    const [bx,by]=shape.bombCell;
    const dir=badgeDirection(shape);
    const ghost=role==='ghost';
    const size=ghost?Math.max(17,Math.min(21,u*.62)):Math.max(12,Math.min(15,u*.64));
    const cx=bx*(u+g)+u/2;
    const cy=by*(u+g)+u/2;
    const step=u/2+size/2+(ghost?3:2);
    const delta={n:[0,-step],e:[step,0],s:[0,step],w:[-step,0]}[dir];

    const badge=document.createElement('b');
    badge.className=`bomb-fuse-badge-v145 bomb-fuse-${dir}-v145${ghost?' ghost':''}`;
    badge.textContent=String(shape.bombFuse||4);
    badge.style.left=`${cx+delta[0]}px`;
    badge.style.top=`${cy+delta[1]}px`;
    badge.style.width=`${size}px`;
    badge.style.height=`${size}px`;
    art.appendChild(badge);

    return art;
  };

  queueMicrotask(()=>{try{if(state?.mode==='BOMBS')renderTray();}catch(_){ }});
})();


/* ===== hotfix-v146.js ===== */
/* GRID SHIFT v1.4.6 — make the current BOMBS clear rule authoritative.
   Current rule:
   - A normal row/column clear that touches a bomb triggers a controlled blast.
   - That bomb clears its visible 3x3 area.
   - Any bomb inside that 3x3 chains, and each chained bomb clears its own 3x3.
   - Fuse expiry remains game over (handled by the existing v1.3.9+ timer rule).
*/
(function(){
  'use strict';

  const previousClearBombsAt=clearBombsAt;

  function key(x,y){return `${x},${y}`;}
  function inBoard(x,y){return x>=0&&y>=0&&x<state.size&&y<state.size;}
  function cheb(a,b){return Math.max(Math.abs(a.x-b.x),Math.abs(a.y-b.y));}

  function blastCells(b){
    const out=[];
    for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){
      const x=b.x+dx,y=b.y+dy;
      if(inBoard(x,y))out.push([x,y]);
    }
    return out;
  }

  function chainFrom(seeds){
    const queue=seeds.slice(),seen=new Set(),out=[];
    while(queue.length){
      const b=queue.shift(),k=key(b.x,b.y);
      if(seen.has(k))continue;
      seen.add(k);out.push(b);
      for(const other of state.bombs||[]){
        const ok=key(other.x,other.y);
        if(!seen.has(ok)&&cheb(b,other)<=1)queue.push(other);
      }
    }
    return out;
  }

  function flashBlast(chain){
    const snapshot=chain.map(b=>({x:b.x,y:b.y}));
    setTimeout(()=>{
      if(!boardEl||!cellEls?.length)return;
      for(const b of snapshot){
        const minX=Math.max(0,b.x-1),maxX=Math.min(state.size-1,b.x+1);
        const minY=Math.max(0,b.y-1),maxY=Math.min(state.size-1,b.y+1);
        const a=cellEls[minY]?.[minX],z=cellEls[maxY]?.[maxX];
        if(!a||!z)continue;
        const f=document.createElement('i');
        f.className='bomb-blast-box-v146'+(snapshot.length>1?' chain':'');
        f.style.left=`${a.offsetLeft-1}px`;
        f.style.top=`${a.offsetTop-1}px`;
        f.style.width=`${z.offsetLeft+z.offsetWidth-a.offsetLeft+2}px`;
        f.style.height=`${z.offsetTop+z.offsetHeight-a.offsetTop+2}px`;
        boardEl.appendChild(f);
        setTimeout(()=>f.remove(),650);
      }
    },0);
  }

  clearBombsAt=function(cells){
    if(state?.mode!=='BOMBS')return previousClearBombsAt(cells);
    if(!Array.isArray(cells)||!cells.length||!Array.isArray(state.bombs)||!state.bombs.length)return;

    const cleared=new Set(cells.map(([x,y])=>key(x,y)));
    const seeds=state.bombs.filter(b=>cleared.has(key(b.x,b.y)));
    if(!seeds.length)return;

    const chain=chainFrom(seeds);
    const chainKeys=new Set(chain.map(b=>key(b.x,b.y)));
    const blastSet=new Set();
    for(const b of chain)for(const [x,y] of blastCells(b))blastSet.add(key(x,y));

    let extra=0;
    for(const k of blastSet){
      const [x,y]=k.split(',').map(Number);
      if(state.board[y][x])extra++;
      state.board[y][x]=0;
    }
    state.bombs=state.bombs.filter(b=>!chainKeys.has(key(b.x,b.y)));

    const n=chain.length;
    const gain=140*n + 100*(n*(n-1)/2) + extra*4;
    state.score+=gain;
    state.bombLastBlast={count:n,gain};

    const fxCells=[...blastSet].map(k=>k.split(',').map(Number));
    if(fxCells.length)queueFx('burst',{cells:fxCells,wave:0});
    flashBlast(chain);
  };
})();

